-- อัปเดตครั้งที่ 3: ข้อมูลจำลอง ชื่อ/ประวัติผู้บริหาร + ประวัติครู (บุคคลสมมติ ไม่ใช่ข้อมูลจริง)
-- วางทั้งไฟล์ใน TiDB Cloud SQL Editor → Ctrl+A → Run (รันซ้ำได้ ไม่ทับประวัติที่แก้เองแล้ว ยกเว้นผู้บริหารที่ยังเป็น (รอระบุชื่อ))
USE ptc_schedule;
SET NAMES utf8mb4;

UPDATE `users` SET `fullName` = 'ดร.สมบัติ วงศ์ประเสริฐ', `bio` = 'การศึกษา:\n- ปริญญาเอก ปรัชญาดุษฎีบัณฑิต สาขาการบริหารการศึกษา\n- ปริญญาโท ครุศาสตร์อุตสาหกรรมมหาบัณฑิต สาขาเทคโนโลยีเครื่องกล\n- ปริญญาตรี ครุศาสตร์อุตสาหกรรมบัณฑิต สาขาวิศวกรรมเครื่องกล\nประสบการณ์:\n- ผู้อำนวยการสถานศึกษา 8 ปี\n- รองผู้อำนวยการฝ่ายวิชาการ 6 ปี\n- ครูแผนกวิชาช่างยนต์ 12 ปี\nผลงาน: ผู้บริหารสถานศึกษาดีเด่น ระดับภาค\n※ ข้อมูลจำลองเพื่อทดสอบระบบ', `phone` = '0421000001', `email` = 'director@ptc.ac.th' WHERE `username` = 'EXEC-01' AND `fullName` = '(รอระบุชื่อ)';
UPDATE `users` SET `fullName` = 'นางสาวพิมพ์ชนก แสงทอง', `bio` = 'การศึกษา:\n- ปริญญาโท บริหารธุรกิจมหาบัณฑิต\n- ปริญญาตรี บัญชีบัณฑิต\nประสบการณ์:\n- รองผู้อำนวยการฝ่ายบริหารทรัพยากร 4 ปี\n- หัวหน้างานการเงินและงานพัสดุ 7 ปี\n- ครูแผนกวิชาการบัญชี 10 ปี\n※ ข้อมูลจำลองเพื่อทดสอบระบบ', `phone` = '0421000002', `email` = 'resource@ptc.ac.th' WHERE `username` = 'EXEC-02' AND `fullName` = '(รอระบุชื่อ)';
UPDATE `users` SET `fullName` = 'นายธีรพงษ์ บุญประเสริฐ', `bio` = 'การศึกษา:\n- ปริญญาโท วิทยาศาสตรมหาบัณฑิต สาขาเทคโนโลยีสารสนเทศ\n- ปริญญาตรี ครุศาสตร์อุตสาหกรรมบัณฑิต สาขาวิศวกรรมอิเล็กทรอนิกส์\nประสบการณ์:\n- รองผู้อำนวยการฝ่ายแผนงานและความร่วมมือ 3 ปี\n- หัวหน้างานศูนย์ข้อมูลสารสนเทศ 6 ปี\n- ครูแผนกวิชาช่างอิเล็กทรอนิกส์ 9 ปี\nผลงาน: พัฒนาระบบสารสนเทศเพื่อการบริหารสถานศึกษา\n※ ข้อมูลจำลองเพื่อทดสอบระบบ', `phone` = '0421000003', `email` = 'plan@ptc.ac.th' WHERE `username` = 'EXEC-03' AND `fullName` = '(รอระบุชื่อ)';
UPDATE `users` SET `fullName` = 'นางวราภรณ์ ศรีวงศ์', `bio` = 'การศึกษา:\n- ปริญญาโท การศึกษามหาบัณฑิต สาขาจิตวิทยาการแนะแนว\n- ปริญญาตรี บริหารธุรกิจบัณฑิต สาขาการตลาด\nประสบการณ์:\n- รองผู้อำนวยการฝ่ายพัฒนากิจการนักเรียนนักศึกษา 5 ปี\n- หัวหน้างานแนะแนวอาชีพและการจัดหางาน 6 ปี\n- ครูแผนกวิชาการตลาด 11 ปี\nผลงาน: ครูที่ปรึกษาองค์การวิชาชีพดีเด่น\n※ ข้อมูลจำลองเพื่อทดสอบระบบ', `phone` = '0421000004', `email` = 'student@ptc.ac.th' WHERE `username` = 'EXEC-04' AND `fullName` = '(รอระบุชื่อ)';
UPDATE `users` SET `fullName` = 'นายอนุชา พลราช', `bio` = 'การศึกษา:\n- ปริญญาโท ครุศาสตร์อุตสาหกรรมมหาบัณฑิต สาขาหลักสูตรและการสอน\n- ปริญญาตรี ครุศาสตร์อุตสาหกรรมบัณฑิต สาขาวิศวกรรมไฟฟ้า\nประสบการณ์:\n- รองผู้อำนวยการฝ่ายวิชาการ 4 ปี\n- หัวหน้างานพัฒนาหลักสูตรการเรียนการสอน 5 ปี\n- ครูแผนกวิชาช่างไฟฟ้ากำลัง 13 ปี\nผลงาน: พัฒนาหลักสูตรระบบทวิภาคีร่วมกับสถานประกอบการ\n※ ข้อมูลจำลองเพื่อทดสอบระบบ', `phone` = '0421000005', `email` = 'academic.vp@ptc.ac.th' WHERE `username` = 'EXEC-05' AND `fullName` = '(รอระบุชื่อ)';

UPDATE `users` SET `bio` = CASE `department`
  WHEN 'คอมพิวเตอร์ธุรกิจ' THEN CONCAT('การศึกษา: ปริญญาตรี บริหารธุรกิจบัณฑิต สาขาคอมพิวเตอร์ธุรกิจ\nประสบการณ์สอน: ', MOD(`id`, 18) + 2, ' ปี\nความเชี่ยวชาญ: งานสอนและพัฒนาสื่อการเรียนรู้แผนกวิชาคอมพิวเตอร์ธุรกิจ\n※ ข้อมูลจำลองเพื่อทดสอบระบบ')
  WHEN 'การบัญชี' THEN CONCAT('การศึกษา: ปริญญาตรี บัญชีบัณฑิต\nประสบการณ์สอน: ', MOD(`id`, 18) + 2, ' ปี\nความเชี่ยวชาญ: งานสอนและพัฒนาสื่อการเรียนรู้แผนกวิชาการบัญชี\n※ ข้อมูลจำลองเพื่อทดสอบระบบ')
  WHEN 'ช่างยนต์' THEN CONCAT('การศึกษา: ปริญญาตรี ครุศาสตร์อุตสาหกรรมบัณฑิต สาขาวิศวกรรมเครื่องกล\nประสบการณ์สอน: ', MOD(`id`, 18) + 2, ' ปี\nความเชี่ยวชาญ: งานสอนและพัฒนาสื่อการเรียนรู้แผนกวิชาช่างยนต์\n※ ข้อมูลจำลองเพื่อทดสอบระบบ')
  WHEN 'ช่างไฟฟ้ากำลัง' THEN CONCAT('การศึกษา: ปริญญาตรี ครุศาสตร์อุตสาหกรรมบัณฑิต สาขาวิศวกรรมไฟฟ้า\nประสบการณ์สอน: ', MOD(`id`, 18) + 2, ' ปี\nความเชี่ยวชาญ: งานสอนและพัฒนาสื่อการเรียนรู้แผนกวิชาช่างไฟฟ้ากำลัง\n※ ข้อมูลจำลองเพื่อทดสอบระบบ')
  WHEN 'ช่างอิเล็กทรอนิกส์' THEN CONCAT('การศึกษา: ปริญญาตรี ครุศาสตร์อุตสาหกรรมบัณฑิต สาขาวิศวกรรมอิเล็กทรอนิกส์\nประสบการณ์สอน: ', MOD(`id`, 18) + 2, ' ปี\nความเชี่ยวชาญ: งานสอนและพัฒนาสื่อการเรียนรู้แผนกวิชาช่างอิเล็กทรอนิกส์\n※ ข้อมูลจำลองเพื่อทดสอบระบบ')
  WHEN 'ช่างเชื่อมโลหะ' THEN CONCAT('การศึกษา: ปริญญาตรี ครุศาสตร์อุตสาหกรรมบัณฑิต สาขาวิศวกรรมการผลิตและเชื่อมประกอบ\nประสบการณ์สอน: ', MOD(`id`, 18) + 2, ' ปี\nความเชี่ยวชาญ: งานสอนและพัฒนาสื่อการเรียนรู้แผนกวิชาช่างเชื่อมโลหะ\n※ ข้อมูลจำลองเพื่อทดสอบระบบ')
  WHEN 'การตลาด' THEN CONCAT('การศึกษา: ปริญญาตรี บริหารธุรกิจบัณฑิต สาขาการตลาด\nประสบการณ์สอน: ', MOD(`id`, 18) + 2, ' ปี\nความเชี่ยวชาญ: งานสอนและพัฒนาสื่อการเรียนรู้แผนกวิชาการตลาด\n※ ข้อมูลจำลองเพื่อทดสอบระบบ')
  WHEN 'เทคโนโลยีสารสนเทศ' THEN CONCAT('การศึกษา: ปริญญาตรี วิทยาศาสตรบัณฑิต สาขาเทคโนโลยีสารสนเทศ\nประสบการณ์สอน: ', MOD(`id`, 18) + 2, ' ปี\nความเชี่ยวชาญ: งานสอนและพัฒนาสื่อการเรียนรู้แผนกวิชาเทคโนโลยีสารสนเทศ\n※ ข้อมูลจำลองเพื่อทดสอบระบบ')
  WHEN 'สามัญสัมพันธ์' THEN CONCAT('การศึกษา: ปริญญาตรี ครุศาสตรบัณฑิต (การสอนวิชาสามัญ)\nประสบการณ์สอน: ', MOD(`id`, 18) + 2, ' ปี\nความเชี่ยวชาญ: งานสอนและพัฒนาสื่อการเรียนรู้แผนกวิชาสามัญสัมพันธ์\n※ ข้อมูลจำลองเพื่อทดสอบระบบ')
  END
  WHERE `role` = 'TEACHER' AND `boardOrder` IS NULL AND `bio` IS NULL;
UPDATE `users` SET `bio` = 'เจ้าหน้าที่งานพัฒนาหลักสูตรการเรียนการสอน ฝ่ายวิชาการ\n※ ข้อมูลจำลองเพื่อทดสอบระบบ' WHERE `role` = 'ADMIN' AND `bio` IS NULL;
